#include <stdio.h>
#include <stdlib.h>
typedef struct{int*data;int count,head,tail,capacity;}Q;int main(void){Q q={0,0,0,0,5};q.data=calloc(q.capacity,sizeof(int));if(!q.data)return 1;int s=0;q.data[q.tail]=11;q.tail++;if(q.tail==5)q.tail=0;q.count++;q.data[q.tail]=22;q.tail++;if(q.tail==5)q.tail=0;q.count++;q.data[q.tail]=33;q.tail++;if(q.tail==5)q.tail=0;q.count++;printf("first %d %d\n",q.count,q.data[q.head]);s+=q.data[q.head];q.head++;if(q.head==5)q.head=0;q.count--;q.data[q.tail]=44;q.tail++;if(q.tail==5)q.tail=0;q.count++;q.data[q.tail]=55;q.tail++;if(q.tail==5)q.tail=0;q.count++;printf("second %d %d\n",q.count,q.data[q.head]);while(q.count){s+=q.data[q.head];q.head++;if(q.head==5)q.head=0;q.count--;}printf("last %d %d\n",q.count,s);free(q.data);return 0;}
